import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"FAQ — Apple","description":"Frequently asked questions about the Apple admin theme for Pterodactyl — compatibility, updates, performance, mobile and the dashboard patch.","frontmatter":{"title":"FAQ — Apple","description":"Frequently asked questions about the Apple admin theme for Pterodactyl — compatibility, updates, performance, mobile and the dashboard patch."},"headers":[],"relativePath":"apple/getting-started/faq.md","filePath":"apple/getting-started/faq.md","lastUpdated":1785521346000}'),r={name:"apple/getting-started/faq.md"};function s(n,e,l,h,d,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="does-apple-replace-any-pterodactyl-core-files" tabindex="-1">Does Apple replace any Pterodactyl core files? <a class="header-anchor" href="#does-apple-replace-any-pterodactyl-core-files" aria-label="Permalink to &quot;Does Apple replace any Pterodactyl core files?&quot;">​</a></h2><p>No — with one deliberate, reversible exception. The theme itself (sidebar, top bar, components, both modes) works entirely through Blueprint&#39;s admin wrapper hook. The <strong>bento dashboard</strong> swaps <code>resources/views/admin/index.blade.php</code>, but the original is backed up next to it first, the patch is marker-verified and idempotent, the stock markup ships inside the patched file as a runtime fallback, and uninstall restores the original. It can also be switched off from the settings hub without uninstalling.</p><h2 id="will-my-other-extensions-still-show-up" tabindex="-1">Will my other extensions still show up? <a class="header-anchor" href="#will-my-other-extensions-still-show-up" aria-label="Permalink to &quot;Will my other extensions still show up?&quot;">​</a></h2><p>Yes — that is the core design. The sidebar is harvested from the panel&#39;s own menu at runtime, so any extension that registers an admin link (Blade marker block, Blueprint sidenav yield, JS injection) appears automatically. Their pages inherit the global component reskin too. See <a href="./../user-guide/compatibility">Extension Compatibility</a>.</p><h2 id="does-it-conflict-with-the-glacier-theme" tabindex="-1">Does it conflict with the Glacier theme? <a class="header-anchor" href="#does-it-conflict-with-the-glacier-theme" aria-label="Permalink to &quot;Does it conflict with the Glacier theme?&quot;">​</a></h2><p>No. Glacier themes the <strong>client</strong> panel (server console, files, dashboard); Apple themes the <strong>admin</strong> area. They are installed side by side and never touch each other&#39;s surfaces.</p><h2 id="what-happens-when-pterodactyl-updates" tabindex="-1">What happens when Pterodactyl updates? <a class="header-anchor" href="#what-happens-when-pterodactyl-updates" aria-label="Permalink to &quot;What happens when Pterodactyl updates?&quot;">​</a></h2><p>Panel updates keep working: no core file is permanently modified. If an update overwrites <code>resources/views/admin/index.blade.php</code>, re-run the dashboard patch by reinstalling (<code>blueprint -i apple-v1.0.0</code> again — it is idempotent) or flip <strong>Bento dashboard</strong> off in the hub.</p><h2 id="what-happens-when-blueprint-itself-is-removed" tabindex="-1">What happens when Blueprint itself is removed? <a class="header-anchor" href="#what-happens-when-blueprint-itself-is-removed" aria-label="Permalink to &quot;What happens when Blueprint itself is removed?&quot;">​</a></h2><p>Without Blueprint there is no wrapper hook, so the theme simply stops rendering and the admin area returns to stock (the dashboard patch remains but is inert markup without Apple&#39;s CSS — remove it with the packaged <code>remove.sh</code> logic or by restoring the backup). If you plan to drop Blueprint permanently, uninstall Apple first.</p><h2 id="is-there-a-performance-cost" tabindex="-1">Is there a performance cost? <a class="header-anchor" href="#is-there-a-performance-cost" aria-label="Permalink to &quot;Is there a performance cost?&quot;">​</a></h2><p>Negligible. One settings read per admin page (Blueprint-cached), five small stylesheets and one script from your own panel, no external requests, no chart library (the sparkline is inline SVG computed server-side). Backdrop blur is GPU-composited and tunable — lower <strong>Glass blur</strong> to <code>0–8</code> on weak hardware.</p><h2 id="does-it-work-on-phones" tabindex="-1">Does it work on phones? <a class="header-anchor" href="#does-it-work-on-phones" aria-label="Permalink to &quot;Does it work on phones?&quot;">​</a></h2><p>Yes. At ≤ 992px the sidebar becomes an off-canvas drawer with a blurred backdrop, the top bar spans full width, tables scroll horizontally instead of breaking layout, and the bento grid collapses to one column (stats stay two-up). Touch targets stay ≥ 34px.</p><h2 id="how-do-per-user-mode-choices-interact-with-the-panel-default" tabindex="-1">How do per-user mode choices interact with the panel default? <a class="header-anchor" href="#how-do-per-user-mode-choices-interact-with-the-panel-default" aria-label="Permalink to &quot;How do per-user mode choices interact with the panel default?&quot;">​</a></h2><p>The hub&#39;s <strong>Default mode</strong> applies until a person flips the top-bar toggle; their choice is stored in that browser and wins thereafter. There is no way (by design) to force a mode on someone who has chosen one — clear the browser&#39;s <code>localStorage</code> (<code>apple-mode</code>) to fall back to the default.</p><h2 id="can-i-use-it-without-blueprint" tabindex="-1">Can I use it without Blueprint? <a class="header-anchor" href="#can-i-use-it-without-blueprint" aria-label="Permalink to &quot;Can I use it without Blueprint?&quot;">​</a></h2><p>Yes — the standalone variant injects one marker-delimited include into the admin layout and otherwise behaves identically, minus the settings hub (defaults apply; values can be adjusted in the <code>settings</code> table). See <a href="./../getting-started/installation#install-standalone">Installation</a>.</p>',19)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
